#!/usr/bin/env node

/**
 * This script is used to reset the project to a blank state.
 * It deletes or moves the /src and /scripts directories to /example based on user input and creates a new /src/app directory with an index.tsx and _layout.tsx file.
 * You can remove the `reset-project` script from package.json and safely delete this file after running it.
 */

const fs = require("fs");
const path = require("path");
const readline = require("readline");

const root = process.cwd();
const oldDirs = ["src", "scripts"];
const exampleDir = "example";
const newAppDir = "src/app";
const exampleDirPath = path.join(root, exampleDir);

const indexContent = `import { Text, View, StyleSheet } from "react-native";

export default function Index() {
  return (
    <View style={styles.container}>
      <Text>Edit src/app/index.tsx to edit this screen.</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
  },
});
`;

const layoutContent = `import { Stack } from "expo-router";

export default function RootLayout() {
  return <Stack />;
}
`;

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const moveDirectories = async (userInput) => {
  try {
    if (userInput === "y") {
      // Create the app-example directory
      await fs.promises.mkdir(exampleDirPath, { recursive: true });
      console.log(`📁 /${exampleDir} directory created.`);
    }

    // Move old directories to new app-example directory or delete them
    for (const dir of oldDirs) {
      const oldDirPath = path.join(root, dir);
      if (fs.existsSync(oldDirPath)) {
        if (userInput === "y") {
          const newDirPath = path.join(root, exampleDir, dir);
          await fs.promises.rename(oldDirPath, newDirPath);
          console.log(`➡️ /${dir} moved to /${exampleDir}/${dir}.`);
        } else {
          await fs.promises.rm(oldDirPath, { recursive: true, force: true });
          console.log(`❌ /${dir} deleted.`);
        }
      } else {
        console.log(`➡️ /${dir} does not exist, skipping.`);
      }
    }

    // Create new /src/app directory
    const newAppDirPath = path.join(root, newAppDir);
    await fs.promises.mkdir(newAppDirPath, { recursive: true });
    console.log("\n📁 New /src/app directory created.");

    // Create index.tsx
    const indexPath = path.join(newAppDirPath, "index.tsx");
    await fs.promises.writeFile(indexPath, indexContent);
    console.log("📄 src/app/index.tsx created.");

    // Create _layout.tsx
    const layoutPath = path.join(newAppDirPath, "_layout.tsx");
    await fs.promises.writeFile(layoutPath, layoutContent);
    console.log("📄 src/app/_layout.tsx created.");

    console.log("\n✅ Project reset complete. Next steps:");
    console.log(
      `1. Run \`npx expo start\` to start a development server.\n2. Edit src/app/index.tsx to edit the main screen.\n3. Put all your application code in /src, only screens and layout files should be in /src/app.${
        userInput === "y"
          ? `\n4. Delete the /${exampleDir} directory when you're done referencing it.`
          : ""
      }`
    );
  } catch (error) {
    console.error(`❌ Error during script execution: ${error.message}`);
  }
};

rl.question(
  "Do you want to move existing files to /example instead of deleting them? (Y/n): ",
  (answer) => {
    const userInput = answer.trim().toLowerCase() || "y";
    if (userInput === "y" || userInput === "n") {
      moveDirectories(userInput).finally(() => rl.close());
    } else {
      console.log("❌ Invalid input. Please enter 'Y' or 'N'.");
      rl.close();
    }
  }
);

import { Task } from '../model/Task';
import { TaskRepository } from './TaskRepository';
import { getDatabaseInstance } from '../database/database';


export class SqliteTaskRepository implements TaskRepository {
  async getTaskById(id: string): Promise<Task | null> {
    const db = await getDatabaseInstance();
    const row = await db.getFirstAsync<any>('SELECT * FROM tasks WHERE id = ?', [id]);
    return row ? this.mapRow(row) : null;
  }

  async getAllTasks(): Promise<Task[]> {
    const db = await getDatabaseInstance();
    const rows = await db.getAllAsync<any>('SELECT * FROM tasks ORDER BY createdAt DESC');
    return rows.map(this.mapRow);
  }

  async createTask(task: Task): Promise<void> {
    const db = await getDatabaseInstance()
    await db.runAsync(
        'INSERT INTO tasks (id, title, description, isCompleted, createdAt) VALUES (?, ?, ?, ?, ?)',
      [task.id, task.title, task.description, task.isCompleted ? 1 : 0, task.createdAt]
    )
  }

  async updateTask(id: string, title: string, description: string): Promise<void> {
    const db = await getDatabaseInstance()
    await db.runAsync('UPDATE tasks SET title = ?, description = ? WHERE id = ?', [title, description, id]);
  }

  async deleteTask(id: string): Promise<void> {
    const db = await getDatabaseInstance()
    await db.runAsync('DELETE FROM tasks WHERE id = ?', [id]);
  }

  async toggleCompleted(id: string): Promise<void> {
    const db = await getDatabaseInstance()
    await db.runAsync('UPDATE tasks SET isCompleted = NOT isCompleted WHERE id = ?', [id]);
  }

  private mapRow(row: any): Task {
    return {
      id: row.id,
      title: row.title,
      description: row.description,
      isCompleted: !!row.isCompleted,
      createdAt: row.createdAt,
    };
  }
}

import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { NavigationContainer } from '@react-navigation/native';
import { TaskListScreen } from '@/presentation/ui/screens/TaskListScreen';
import { TaskDetailScreen } from '@/presentation/ui/screens/TaskDetailScreen';
import { TaskFormScreen } from '@/presentation/ui/screens/TaskFormScreen';
import { RootStackParamList } from './types';

const Stack = createNativeStackNavigator<RootStackParamList>();

export function AppNavigation() {
  return (
    <NavigationContainer>
        <Stack.Navigator initialRouteName = "TaskList"
        screenOptions={{
            headerStyle: { backgroundColor: '#6650A4' },
            headerTintColor: '#fff',
            headerTitleStyle: { fontWeight: '700' },
        }}>
            <Stack.Screen name="TaskList" component={TaskListScreen} options={{ title: 'Minhas Tarefas' }} />
            <Stack.Screen name="TaskDetail" component={TaskDetailScreen} options={{ title: 'Detalhes' }} />
            <Stack.Screen name="TaskForm" component={ TaskFormScreen} options={({ route }) => ({ title: route.params?.id ? 'Editar Tarefa' : 'Nova Tarefa' })} />
        </Stack.Navigator>
    </NavigationContainer>
  );
}

import React, { useEffect } from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
import type { NativeStackScreenProps } from '@react-navigation/native-stack';
import type { RootStackParamList } from '../../navigation/types';
import { Feather } from '@expo/vector-icons';
import { useTaskStore } from '@/di/AppModule';

type Props = NativeStackScreenProps<RootStackParamList, 'TaskDetail'>;

export function TaskDetailScreen({ route, navigation }: Props) {
  const { id } = route.params;
  const { selectedTask, loadTaskDetails, deleteTask } = useTaskStore();

  useEffect(() => {
    const unsubscribe = navigation.addListener('focus', () => {
          loadTaskDetails(id)

    });
    return unsubscribe;
  }, [id, navigation])

  return (
    <View style={styles.container}>
      <Text style={styles.title}>{selectedTask?.title}</Text>
      <Text style={styles.description}>{selectedTask?.description}</Text>
      <Text style={styles.status}>{selectedTask?.isCompleted}</Text>
    <TouchableOpacity
        style={styles.editButton}
        onPress={() => navigation.navigate('TaskForm', { id })}
      >
          <Feather name="edit-2" size={16} color="#FFFFFF" />

        <Text style={styles.editButtonText}>  Editar tarefa</Text>
      </TouchableOpacity>
      <TouchableOpacity style={styles.deleteButton} onPress={() =>{
        deleteTask
        navigation.goBack()
      }}>
        <Text style={styles.deleteButtonText}>Excluir tarefa</Text>
      </TouchableOpacity>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 20, backgroundColor: '#fff' },
  title: { fontSize: 22, fontWeight: '700', marginBottom: 12 },
  description: { fontSize: 16, color: '#444', marginBottom: 20 },
  status: { fontSize: 14, color: '#6650A4', fontWeight: '600' },
  deleteButton: { marginTop: 40, borderWidth: 1, borderColor: '#D32F2F', borderRadius: 8, padding: 14, alignItems: 'center' },
  deleteButtonText: { color: '#D32F2F', fontWeight: '700' },
  editButton: {
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#5E5CE6',
    borderRadius: 14,
    paddingVertical: 16,
    marginTop: 24,
    gap: 8,
  },
  editButtonText: {
    color: '#FFFFFF',
    fontSize: 16,
    fontWeight: '700',
  },
});
